"use client";

import { Slider as Primitive } from "@base-ui/react/slider";
import { animate, motion, useMotionValue, useTransform } from "motion/react";
import { useEffect, useRef } from "react";
import type { CSSProperties, ReactNode } from "react";

import {
  Tooltip,
  TooltipTrigger,
  TooltipContent,
} from "@/components/ui/tooltip";
import { useMeasure } from "@/hooks/use-measure";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { spring } from "@/lib/motion";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import type { SizeVariant } from "@/lib/size-context";
import { cn } from "@/lib/utils";

export interface SliderProps extends Primitive.Root.Props<
  number | readonly number[]
> {
  label?: string;
  size?: SizeVariant;
  variant?: "comfortable" | "scrubber";
  marks?: readonly (number | { value: number; label?: ReactNode })[];
  tooltip?: boolean;
}

const emptyMarks: NonNullable<SliderProps["marks"]> = [];

export const Slider = ({
  label = "Value",
  size,
  variant = "comfortable",
  marks = emptyMarks,
  tooltip = true,
  className,
  min = 0,
  max = 100,
  step = 1,
  disabled,
  ...props
}: SliderProps) => {
  const sizes = useSize(size);
  const shape = useShape();
  const reduced = useReducedMotion();
  const control = useMeasure();
  const labelMeasure = useMeasure<HTMLSpanElement>();
  const valueMeasure = useMeasure<HTMLOutputElement>();
  const compact = sizes.variant === "compact";
  const target = useRef(0);
  const stretch = useMotionValue(0);
  const x = useTransform(stretch, (distance) => distance / 2);
  const scaleX = useTransform(stretch, (distance) =>
    control.width ? 1 + Math.abs(distance) / control.width : 1
  );

  useEffect(() => {
    if (disabled || reduced) {
      target.current = 0;
      stretch.jump(0);
    }
  }, [disabled, reduced, stretch]);

  useEffect(() => () => stretch.stop(), [stretch]);

  const animateStretch = (distance: number) => {
    if (target.current === distance) {
      return;
    }
    target.current = distance;
    animate(stretch, distance, spring.moderate);
  };

  const releaseStretch = () => animateStretch(0);

  const fraction = (value: number) =>
    max > min ? Math.max(0, Math.min(1, (value - min) / (max - min))) : 0;
  const intervals = step > 0 ? (max - min) / step : 0;
  const ticks = marks.length
    ? marks.map((mark) => (typeof mark === "number" ? mark : mark.value))
    : Array.from(
        { length: intervals > 0 ? Math.min(9, Math.ceil(intervals) - 1) : 0 },
        (_, index) =>
          intervals <= 10
            ? min + (index + 1) * step
            : min + ((index + 1) * (max - min)) / 10
      );

  return (
    <Primitive.Root
      min={min}
      max={max}
      step={step}
      disabled={disabled}
      defaultValue={min}
      thumbAlignment="edge"
      data-slot="slider"
      className={cn("w-full min-w-24 data-[disabled]:opacity-50", className)}
      {...props}
    >
      <Primitive.Control
        ref={control.ref}
        className={cn(
          "group/slider relative flex w-full touch-none items-center select-none outline-none has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring has-[:focus-visible]:ring-offset-2 has-[:focus-visible]:ring-offset-background data-[disabled]:pointer-events-none",
          sizes.control,
          shape
        )}
        onPointerMove={(event) => {
          // Observe Base UI's captured drag only; value and focus stay with the primitive.
          if (
            reduced ||
            disabled ||
            props.orientation === "vertical" ||
            !event.currentTarget.hasPointerCapture(event.pointerId)
          ) {
            return;
          }
          const bounds = event.currentTarget.getBoundingClientRect();
          const overflow =
            event.clientX -
            Math.max(bounds.left, Math.min(event.clientX, bounds.right));
          animateStretch(8 * Math.tanh(overflow / 80));
        }}
        onLostPointerCapture={releaseStretch}
        onPointerUp={releaseStretch}
        onPointerCancel={releaseStretch}
      >
        <motion.div
          data-slot="slider-surface"
          className="absolute inset-0 flex items-center"
          style={{ scaleX: reduced ? 1 : scaleX, x: reduced ? 0 : x }}
        >
          <Primitive.Track
            className={cn(
              "relative w-full overflow-hidden bg-foreground/5",
              compact ? "h-[18px] rounded-full" : ["h-full", shape]
            )}
          >
            <Primitive.Indicator className="absolute h-full bg-foreground/10 transition-colors duration-(--motion-fast) group-hover/slider:bg-foreground/15 group-focus-within/slider:bg-foreground/15 group-data-[dragging]/slider:bg-foreground/15 motion-reduce:transition-none" />
            <div
              aria-hidden="true"
              className={cn(
                "pointer-events-none absolute inset-0 transition-opacity duration-(--motion-fast) motion-reduce:transition-none",
                !marks.length &&
                  "opacity-0 group-hover/slider:opacity-100 group-focus-within/slider:opacity-100 group-data-[dragging]/slider:opacity-100"
              )}
            >
              {ticks.map((value) => (
                <span
                  key={value}
                  className={cn(
                    "absolute top-1/2 w-px -translate-x-1/2 -translate-y-1/2 rounded-full bg-foreground/20",
                    compact ? "h-1" : "h-2"
                  )}
                  style={{ left: `${fraction(value) * 100}%` }}
                />
              ))}
            </div>
            {!compact && (
              <div
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute inset-0 flex items-center justify-between gap-4",
                  sizes.px,
                  sizes.text
                )}
              >
                <span ref={labelMeasure.ref} className="truncate font-medium">
                  {label}
                </span>
                <Primitive.Value
                  ref={valueMeasure.ref}
                  className="shrink-0 text-muted-foreground tabular-nums transition-colors duration-(--motion-fast) group-hover/slider:text-foreground group-focus-within/slider:text-foreground motion-reduce:transition-none"
                />
              </div>
            )}
          </Primitive.Track>
          <Primitive.Value render={<div />}>
            {(formatted, values) =>
              values.map((value, index) => {
                const position = fraction(value) * control.width;
                const overlapsText =
                  !compact &&
                  control.width > 0 &&
                  (position < labelMeasure.width + 24 ||
                    position > control.width - valueMeasure.width - 24);
                return (
                  <Tooltip key={index} disabled={!tooltip}>
                    <TooltipTrigger
                      render={
                        <Primitive.Thumb
                          index={index}
                          getAriaLabel={() =>
                            values.length > 1
                              ? `${label} ${index === 0 ? "minimum" : "maximum"}`
                              : label
                          }
                        />
                      }
                      className={cn(
                        "group/thumb flex items-center justify-center rounded-full outline-none has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ring",
                        compact ? "size-4" : "h-full w-3"
                      )}
                      style={
                        {
                          "--slider-handle-opacity": overlapsText ? 0.15 : 1,
                        } as CSSProperties
                      }
                    >
                      <span
                        aria-hidden="true"
                        className={cn(
                          "pointer-events-none block rounded-full transition-[transform,opacity] duration-(--motion-fast) motion-reduce:transition-none",
                          compact
                            ? "size-4 border border-border bg-background shadow-sm group-hover/thumb:scale-110 group-data-[dragging]/thumb:scale-110 motion-reduce:transform-none"
                            : "w-1 bg-foreground/60 opacity-0 group-hover/slider:opacity-(--slider-handle-opacity) group-focus-within/slider:opacity-(--slider-handle-opacity) group-data-[dragging]/slider:opacity-(--slider-handle-opacity)",
                          !compact && (variant === "scrubber" ? "h-6" : "h-5")
                        )}
                      />
                    </TooltipTrigger>
                    <TooltipContent>{formatted[index]}</TooltipContent>
                  </Tooltip>
                );
              })
            }
          </Primitive.Value>
        </motion.div>
      </Primitive.Control>
      {marks.some((mark) => typeof mark !== "number" && mark.label) && (
        <div className="relative mt-1 h-5 text-xs text-muted-foreground">
          {marks.map((mark) =>
            typeof mark !== "number" && mark.label ? (
              <span
                key={mark.value}
                className="absolute -translate-x-1/2"
                style={{ left: `${fraction(mark.value) * 100}%` }}
              >
                {mark.label}
              </span>
            ) : null
          )}
        </div>
      )}
    </Primitive.Root>
  );
};

"use client";

import { Tooltip as Primitive } from "@base-ui/react/tooltip";
import type { ComponentProps } from "react";

import { useShape } from "@/lib/shape-context";
import { useSurface } from "@/lib/surface-context";
import { cn } from "@/lib/utils";

export const TooltipProvider = ({
  delay = 200,
  ...props
}: ComponentProps<typeof Primitive.Provider>) => (
  <Primitive.Provider delay={delay} {...props} />
);
export const Tooltip = Primitive.Root;
export const TooltipTrigger = Primitive.Trigger;

export const TooltipContent = ({
  className,
  children,
  side = "top",
  align = "center",
  sideOffset = 8,
  alignOffset,
  collisionPadding = 8,
  anchor,
  ...props
}: ComponentProps<typeof Primitive.Popup> &
  Pick<
    ComponentProps<typeof Primitive.Positioner>,
    | "side"
    | "align"
    | "sideOffset"
    | "alignOffset"
    | "collisionPadding"
    | "anchor"
  >) => {
  const shape = useShape();
  const surface = useSurface();
  return (
    <Primitive.Portal>
      <Primitive.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        collisionPadding={collisionPadding}
        anchor={anchor}
        style={{ zIndex: 50 + surface }}
      >
        <Primitive.Popup
          data-slot="tooltip-content"
          className={cn(
            "w-fit max-w-xs bg-foreground px-2 py-1 text-xs text-background origin-(--transform-origin) transition-[opacity,transform] duration-(--motion-fast) data-[ending-style]:duration-(--motion-exit-fast) data-[starting-style]:opacity-0 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[ending-style]:scale-95 motion-reduce:transition-none",
            shape,
            className
          )}
          {...props}
        >
          {children}
        </Primitive.Popup>
      </Primitive.Positioner>
    </Primitive.Portal>
  );
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type ShapeVariant = "rounded" | "pill";
const ShapeContext = createContext<ShapeVariant>("rounded");
export const shapeMap = {
  pill: "rounded-[20px]",
  rounded: "rounded-lg",
} as const;
export const ShapeProvider = ({
  shape,
  children,
}: {
  shape: ShapeVariant;
  children: ReactNode;
}) => <ShapeContext.Provider value={shape}>{children}</ShapeContext.Provider>;
export const useShape = (override?: ShapeVariant) => {
  const inherited = useContext(ShapeContext);
  return shapeMap[override ?? inherited];
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type SizeVariant = "default" | "compact";
const SizeContext = createContext<SizeVariant>("default");
export const sizeMap = {
  compact: {
    control: "h-7",
    controlHeight: 28,
    gap: "gap-1",
    icon: 14,
    iconClass: "[&_svg:not([class*='size-'])]:size-3.5",
    px: "px-2.5",
    text: "text-xs",
    variant: "compact",
  },
  default: {
    control: "h-9",
    controlHeight: 36,
    gap: "gap-2",
    icon: 16,
    iconClass: "[&_svg:not([class*='size-'])]:size-4",
    px: "px-3",
    text: "text-[13px]",
    variant: "default",
  },
} as const;
export const SizeProvider = ({
  size,
  children,
}: {
  size: SizeVariant;
  children: ReactNode;
}) => <SizeContext.Provider value={size}>{children}</SizeContext.Provider>;
export const useSizeVariant = (override?: SizeVariant) => {
  const inherited = useContext(SizeContext);
  return override ?? inherited;
};
export const useSize = (override?: SizeVariant) =>
  sizeMap[useSizeVariant(override)];

"use client";

import { createContext, useContext } from "react";
import type { CSSProperties, ReactNode } from "react";

const SurfaceContext = createContext(1);
export const clampSurface = (level: number) =>
  Number.isFinite(level) ? Math.max(1, Math.min(8, Math.round(level))) : 1;
export const useSurface = () => useContext(SurfaceContext);
export const SurfaceProvider = ({
  value,
  children,
}: {
  value: number;
  children: ReactNode;
}) => (
  <SurfaceContext.Provider value={clampSurface(value)}>
    {children}
  </SurfaceContext.Provider>
);
export const surfaceStyle = (level: number): CSSProperties => ({
  backgroundColor: `var(--surface-${clampSurface(level)})`,
});

"use client";

import { useCallback, useEffect, useState } from "react";

export const useMeasure = <T extends HTMLElement = HTMLDivElement>() => {
  const [element, setElement] = useState<T | null>(null);
  const [size, setSize] = useState({ height: 0, width: 0 });
  const ref = useCallback((node: T | null) => {
    setElement(node);
  }, []);
  useEffect(() => {
    if (!element) {
      return;
    }
    const update = () => {
      const width = element.offsetWidth;
      const height = element.offsetHeight;
      setSize((previous) =>
        previous.width === width && previous.height === height
          ? previous
          : { height, width }
      );
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(element);
    return () => observer.disconnect();
  }, [element]);
  return { ref, ...size };
};

"use client";

import { useMediaQuery } from "@/hooks/use-media-query";

/** False during SSR and the first hydration render; subscribes after mounting. */
export const useReducedMotion = () =>
  useMediaQuery("(prefers-reduced-motion: reduce)");

import { useEffect, useState } from "react";

export const useMediaQuery = (query: string) => {
  const [value, setValue] = useState(false);

  useEffect(() => {
    const onChange = (event: MediaQueryListEvent) => {
      setValue(event.matches);
    };

    const result = matchMedia(query);
    result.addEventListener("change", onChange);
    setValue(result.matches);

    return () => result.removeEventListener("change", onChange);
  }, [query]);

  return value;
};

import type { Transition } from "motion/react";

// Base UI owns presence; CSS consumers use the same timing ladder as Motion.
export const motionClasses = {
  moderate:
    "duration-(--motion-moderate) data-[state=closed]:duration-(--motion-exit-moderate) motion-reduce:animate-none",
  slow: "duration-(--motion-slow) data-[state=closed]:duration-(--motion-exit-slow) motion-reduce:animate-none",
};

// Fluid Functionalism's timing ladder: quick feedback, precise panels, larger moves.
export const spring = {
  fast: { bounce: 0, duration: 0.08, exit: { duration: 0.06 }, type: "spring" },
  moderate: {
    bounce: 0,
    duration: 0.16,
    exit: { duration: 0.12 },
    type: "spring",
  },
  slow: {
    bounce: 0.12,
    duration: 0.24,
    exit: { duration: 0.16 },
    type: "spring",
  },
} as const;

export const motionPresets = {
  activeIndicator: spring.moderate,
  enter: {
    animate: { opacity: 1, scale: 1 },
    initial: { opacity: 0, scale: 0.95 },
    transition: spring.moderate,
  },
  exit: { opacity: 0, scale: 0.95, transition: spring.moderate.exit },
  fade: { duration: spring.fast.duration },
  hover: spring.fast,
  layout: spring.moderate,
  snap: { duration: 0 },
} satisfies Record<string, unknown>;

export const motionTransition = (
  transition: Transition,
  reduced: boolean
): Transition =>
  reduced ? { duration: 0, opacity: motionPresets.fade } : transition;
